import React, { useState } from 'react';

const RegistroEstudianteForm = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({});

  const steps = [
    'Datos del Estudiante',
    'Datos del Nacimiento',
    'Dirección Actual',
    'Datos del Tutor',
  ];

  const handleNext = () => {
    if (step < steps.length) {
      setStep((prev) => prev + 1);
    } else {
      handleSubmit();
    }
  };

  const handlePrev = () => setStep((prev) => Math.max(prev - 1, 1));

  const handleChange = (e) => {
    const { name, value, files, type } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === 'file' ? files[0] : value,
    }));
  };

  const handleSubmit = () => {
    console.log('Datos enviados:', formData);
    alert('Formulario enviado correctamente');
    // Aquí podrías enviar formData a un backend con fetch o axios
  };

  const Tabs = () => (
    <div className="flex justify-between mb-6">
      {steps.map((label, index) => (
        <div
          key={index}
          className={`flex-1 text-center p-2 border-b-4 transition-all duration-300 ${
            step === index + 1
              ? 'border-blue-500 font-bold text-blue-600'
              : 'border-gray-300 text-gray-500'
          }`}
        >
          {label}
        </div>
      ))}
    </div>
  );

  const Buttons = ({ isFinalStep }) => (
    <div className="flex justify-between mt-6">
      <button
        onClick={handlePrev}
        disabled={step === 1}
        className="bg-gray-300 text-gray-800 px-4 py-2 rounded disabled:opacity-50"
      >
        Anterior
      </button>
      <button
        onClick={handleNext}
        className="bg-blue-500 text-white px-4 py-2 rounded"
      >
        {isFinalStep ? 'Finalizar' : 'Siguiente'}
      </button>
    </div>
  );

  const SaveCancel = () => (
    <div className="flex justify-end space-x-4 mt-4">
      <button
        className="bg-green-500 text-white px-4 py-2 rounded"
        onClick={handleSubmit}
      >
        Guardar
      </button>
      <button
        className="bg-red-500 text-white px-4 py-2 rounded"
        onClick={() => {
          setFormData({});
          setStep(1);
        }}
      >
        Cancelar
      </button>
    </div>
  );

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="w-[900px] h-[750px] bg-white shadow-xl p-10 rounded-2xl overflow-y-auto">
        <Tabs />

        {/* Aquí insertas las secciones del formulario (step 1 a 4) */}

        {/* Aquí va el contenido del paso actual, ya lo tienes definido por pasos */}

        {step === 4 && <SaveCancel />}
        <Buttons isFinalStep={step === steps.length} />
      </div>
    </div>
  );
};

export default RegistroEstudianteForm;
